#include <openvdb/openvdb.h>
#include <openvdb/tools/ParticleAtlas.h>
#include <tbb/global_control.h>
#include <fstream>
#include <iomanip>
using namespace openvdb;std::ofstream o;
void num(double v){if(std::isfinite(v))o<<v;else o<<'"'<<(std::isnan(v)?"NaN":v>0?"Infinity":"-Infinity")<<'"';}
template<class V>void vec(const V&v){o<<'[';for(int i=0;i<3;++i){if(i)o<<',';num(v[i]);}o<<']';}
struct Particle{Vec3d position;double radius;};
struct Particles{using PosType=Vec3d;using ScalarType=double;std::vector<Particle> data;size_t size()const{return data.size();}void getPos(size_t n,Vec3d&p)const{p=data.at(n).position;}void getRadius(size_t n,double&r)const{r=data.at(n).radius;}};
Particles particles(int scene){Particles p;if(scene==0)return p;for(int i=0;i<80;++i){Vec3d position(((i*47)%53-26)*.75+.5,((i*29)%41-20)*.5-.5,((i*19)%31-15)*.625+.25);double r=scene==1?.75:scene==2?(.25+(i%7)*.125):scene==3?double(1<<(i%5)):scene==4?(i%4==0?0:double(i%8)*.25):(.5+(i%3)*8);p.data.push_back({position,r});}for(auto pos:{Vec3d(-.5),Vec3d(.5),Vec3d(7.5),Vec3d(-8.5),Vec3d(0),Vec3d(0),Vec3d(256.5),Vec3d(-257)})p.data.push_back({pos,scene==1?.75:scene==2?.5:2});return p;}
math::Transform::Ptr transform(int profile){auto t=math::Transform::createLinearTransform(profile==0?1:.75);if(profile==2){t->postTranslate(Vec3d(.25,-.375,.125));t->postRotate(.2,math::Z_AXIS);}if(profile==3)t->postScale(Vec3d(1,2,3));if(profile==4)t=math::Transform::createFrustumTransform(BBoxd(Vec3d(-20),Vec3d(20)),.7,20,.5);return t;}
void grid(const tools::PointIndexGrid&g){o<<"{\"active\":"<<g.activeVoxelCount()<<",\"roots\":"<<g.tree().root().getTableSize()<<",\"nodes\":[";auto counts=g.tree().nodeCount();for(size_t i=0;i<counts.size();++i){if(i)o<<',';o<<counts[i];}o<<"],\"voxelSize\":";vec(g.voxelSize());o<<",\"zero\":";vec(g.indexToWorld(Vec3d(0)));o<<",\"leaves\":[";bool first=true;for(auto it=g.tree().cbeginLeaf();it;++it){if(!first)o<<',';first=false;o<<"{\"origin\":";vec(it->origin());o<<",\"indices\":[";for(size_t i=0;i<it->indices().size();++i){if(i)o<<',';o<<uint32_t(it->indices()[i]);}o<<"],\"runs\":[";for(int i=0;i<512;){if(i)o<<',';auto v=it->getValue(i);bool on=it->isValueOn(i);int end=i+1;while(end<512&&it->getValue(end)==v&&it->isValueOn(end)==on)++end;o<<'['<<end-i<<','<<uint32_t(v)<<','<<on<<']';i=end;}o<<"]}";}o<<"]}";}
template<class Iter>void indices(Iter&it){o<<'[';bool first=true;for(;it;++it){if(!first)o<<',';first=false;o<<uint32_t(*it);}o<<']';}
Vec3d center(int n){return n<3?Vec3d(0):n==3?Vec3d(.5):n==4?Vec3d(-7.5,1,2):Vec3d(15,-6,5);}
double radius(int n){double values[]={0,.5,1,3,7,15};return values[n];}
void pointQueries(const tools::PointIndexGrid&g,const Particles&p){o<<'[';auto acc=g.getConstAccessor();bool first=true;for(int kind=0;kind<7;++kind)for(int q=0;q<6;++q){if(!first)o<<',';first=false;tools::PointIndexIterator<> it;Vec3d c=center(q);double r=radius(q);BBoxd box(c-Vec3d(r),c+Vec3d(r));CoordBBox cb(Coord::round(box.min()),Coord::round(box.max()));if(kind==0)it.searchAndUpdate(Coord::round(c),acc);if(kind==1)it.searchAndUpdate(cb,acc);if(kind==2)it.searchAndUpdate(box,acc,p,g.transform());if(kind==3)it.searchAndUpdate(c,r,acc,p,g.transform(),true);if(kind==4)it.searchAndUpdate(c,r,acc,p,g.transform(),false);if(kind==5)it.worldSpaceSearchAndUpdate(box,acc,p,g.transform());if(kind==6)it.worldSpaceSearchAndUpdate(c,r,acc,p,g.transform(),true);o<<"{\"kind\":"<<kind<<",\"query\":"<<q<<",\"indices\":";indices(it);o<<'}';}o<<']';}
void pointCase(int scene,int tr){Particles p=particles(scene);auto g=tools::createPointIndexGrid<tools::PointIndexGrid>(p,*transform(tr));o<<"{\"scene\":"<<scene<<",\"transform\":"<<tr<<",\"grid\":";grid(*g);o<<",\"valid\":"<<tools::isValidPartition(p,*g)<<",\"queries\":";pointQueries(*g,p);o<<'}';}
void atlasCase(int scene,int profile,int limit){Particles p=particles(scene);double minVoxel=profile==0?.125:profile==1?1:3;tools::ParticleIndexAtlas atlas;atlas.construct(p,minVoxel,limit);o<<"{\"scene\":"<<scene<<",\"profile\":"<<profile<<",\"limit\":"<<limit<<",\"levels\":[";for(size_t i=0;i<atlas.levels();++i){if(i)o<<',';o<<"{\"minimum\":";num(atlas.minRadius(i));o<<",\"maximum\":";num(atlas.maxRadius(i));o<<",\"grid\":";grid(atlas.pointIndexGrid(i));o<<'}';}o<<"],\"levelIndices\":[";tools::ParticleIndexAtlas::Iterator it(atlas);for(size_t i=0;i<atlas.levels()+2;++i){if(i)o<<',';it.updateFromLevel(i);indices(it);}o<<"],\"queries\":[";if(p.size())for(int kind=0;kind<2;++kind)for(int q=0;q<6;++q){if(kind||q)o<<',';Vec3d c=center(q);double r=radius(q);if(kind==0)it.worldSpaceSearchAndUpdate(c,r,p);else it.worldSpaceSearchAndUpdate(BBoxd(c-Vec3d(r),c+Vec3d(r)),p);o<<"{\"kind\":"<<kind<<",\"query\":"<<q<<",\"indices\":";indices(it);o<<'}';}o<<"]}";}
int main(int argc,char**argv){initialize();tbb::global_control serial(tbb::global_control::max_allowed_parallelism,1);o.open(argv[1]);o<<std::setprecision(17)<<"{\"upstreamCommit\":\"f42248c35a9f7bb30641a8a74d9075ce7d1ddcaf\",\"grids\":[";bool first=true;for(int scene=0;scene<6;++scene)for(int t=0;t<5;++t){if(!first)o<<',';first=false;pointCase(scene,t);}o<<"],\"cases\":[";first=true;for(int scene=0;scene<6;++scene)for(int p=0;p<3;++p)for(int limit:{0,1,2,3,50}){if(!first)o<<',';first=false;atlasCase(scene,p,limit);}o<<"]}";return o?0:1;}
